def experiments_dir() -> Path:
    """Backward-compat alias for global_dir()."""
    return global_dir()


def project_dir(project: str) -> Path:
    """Per-project root — all project data lives here."""
    return WORKSPACE_ROOT / "projects" / project


def project_docs_dir(project: str) -> Path:
    """Per-project human-readable docs (MODELS.md, ARCHITECTURE.md, README.md, etc.).

    New layout: projects/{project}/docs/
    Fallback:   projects/{project}/  (un-migrated projects)
    """
    return WORKSPACE_ROOT / "projects" / project / "docs"

def _write_visual_review_timestamp(
    pdf_path: str, pages_reviewed: int, *, source: str = "manual",
) -> None:
    """Write _last_visual_review.json to the project directory for the submit gate."""
    p = Path(pdf_path)
    for parent in p.parents:
        if (parent / "paper_provenance.yaml").exists() or parent.name == "paper":
            project_dir = parent.parent if parent.name == "paper" else parent
            review_file = project_dir / "_last_visual_review.json"
            review_file.write_text(json.dumps({
                "timestamp": datetime.now(timezone.utc).isoformat(),
                "pages_reviewed": pages_reviewed,
                "source": source,
            }))
            return


